#include <vector>
#include <queue>

using namespace std;

class TopKTemplate {
public:
    // Generic Min-Heap template to find the K largest elements
    vector<int> findKLargestElements(const vector<int>& nums, int k) {
        // Min-heap declaration
        priority_queue<int, vector<int>, greater<int>> minHeap;

        // Push first K elements onto the heap
        for (int i = 0; i < k; ++i) {
            if (i < nums.size()) {
                minHeap.push(nums[i]);
            }
        }

        // For the remaining elements, push only if larger than the root
        for (int i = k; i < nums.size(); ++i) {
            if (nums[i] > minHeap.top()) {
                minHeap.pop();
                minHeap.push(nums[i]);
            }
        }

        // Extract elements from the heap
        vector<int> result;
        while (!minHeap.empty()) {
            result.push_back(minHeap.top());
            minHeap.pop();
        }

        return result;
    }
};

